# shellcheck source=lib/ci-shim.sh
source "$(dirname "${BASH_SOURCE[0]}")/lib/ci-shim.sh"

: "${MDF_SONAR_HOST_URL=}"
: "${MDF_SONAR_TOKEN=}"

# >>> extracted body
echo "[DEBUG] ====== SonarQube Quality Gate Check ======"
echo "[DEBUG] Waiting 10s for SonarQube to process analysis..."
sleep 10

ANALYSIS_ID=$(curl -s -u "${MDF_SONAR_TOKEN}:" \
  "${MDF_SONAR_HOST_URL}/api/project_analyses/search?project=$(ci_repo_name)&ps=1" \
  | jq -r '.analyses[0].key')

echo "[DEBUG] Analysis ID: $ANALYSIS_ID"

if [ -z "$ANALYSIS_ID" ] || [ "$ANALYSIS_ID" = "null" ]; then
  ci_log_warning "Could not retrieve analysis ID. Skipping quality gate check."
  exit 0
fi

STATUS=$(curl -s -u "${MDF_SONAR_TOKEN}:" \
  "${MDF_SONAR_HOST_URL}/api/qualitygates/project_status?analysisId=$ANALYSIS_ID" \
  | jq -r '.projectStatus.status')

echo "[DEBUG] Quality Gate Status: $STATUS"

if [ "$STATUS" != "OK" ]; then
  ci_log_error "SonarQube Quality Gate FAILED. Review issues at ${MDF_SONAR_HOST_URL}/dashboard?id=$(ci_repo_name)"
  ci_complete_failed "Quality Gate not met"
  exit 1
fi

echo "[DEBUG] Quality Gate PASSED"
